CREATE OR REPLACE FUNCTION public.is_company_admin(_cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.company_access_active(_cid) AND EXISTS(SELECT 1 FROM public.company_members WHERE user_id=auth.uid() AND company_id=_cid AND role='admin') $$;
CREATE OR REPLACE FUNCTION public.is_company_member(_cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.company_access_active(_cid) AND EXISTS(SELECT 1 FROM public.company_members WHERE user_id=auth.uid() AND company_id=_cid) $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.slug_problem(text)'::regprocedure) INTO def; def := replace(def,'''empresa'',''empresas'']', '''empresa'',''empresas'',''assinatura'']'); EXECUTE def; END $$;